let TracesPlusPageviews = 
    allTraces 
    | union pageViews 
    | where timestamp between (_startTime .. _endTime)
    | count 
    | extend Desc = 'traces + pageViews'; 
let BaseCustomers = 
    allTraces 
    | count 
    | extend Desc = 'allTraces';
TracesPlusPageviews
| union BaseCustomers

allTraces
| where isnotempty( customDimensions.requestQueueTime)
| extend endpoint = tostring(customDimensions.endpoint)
, ObjectName = tostring(customDimensions.alObjectName)
, serverExecutionTimeInMS = toreal(totimespan(customDimensions.serverExecutionTime))/10000 
, totalTimeInMS = toreal(totimespan(customDimensions.totalTime))/10000 
, requestQueueTimeInMS = toreal(totimespan(customDimensions.requestQueueTime))/10000
| where requestQueueTimeInMS > 0
| where ObjectName contains _sourceObjectFilter
| summarize count(), avg(requestQueueTimeInMS) by bin(timestamp, 1h), endpoint, tenantDescription //put endpoint and customer in the graph


